def max_Product(arr):
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements to form a pair.")

    # Initialize variables to find the two largest and two smallest numbers
    max1 = max2 = float('-inf')  # Two largest numbers
    min1 = min2 = float('inf')   # Two smallest numbers

    # Traverse the array to find the two largest and two smallest numbers
    for num in arr:
        # Update largest numbers
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update smallest numbers
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Compute products
    product1 = max1 * max2
    product2 = min1 * min2

    # Return the pair with the highest product
    if product1 > product2:
        return (max1, max2) if max1 >= max2 else (max2, max1)
    else:
        return (min1, min2) if min1 <= min2 else (min2, min1)

# Example usage and tests
assert max_Product([1, 2, 3, 4, 7, 0, 8, 4]) == (7, 8)
assert max_Product([-10, -20, 1, 3, 2]) == (-20, -10)
assert max_Product([5, 6]) == (5, 6)
assert max_Product([0, -1, -2, -3, -4]) == (-4, -3)
